<?php
/** Tasks, delegations and bounded automation template. */
defined( 'ABSPATH' ) || exit;
$title_id = $instance_id . '-tasks-title';
$can_tasks = SPDB_Capabilities::current_user_can( 'spdb_manage_tasks' );
$can_delegate = SPDB_Capabilities::current_user_can( 'spdb_manage_delegations' );
$can_rules = SPDB_Capabilities::current_user_can( 'spdb_manage_automation_rules' );
?>
<section class="spdb-operations-section" aria-labelledby="<?php echo esc_attr( $title_id ); ?>">
	<p class="spdb-eyebrow"><?php esc_html_e( 'File 23-owned operational metadata', 'sabri-publishing-dashboard' ); ?></p>
	<h2 id="<?php echo esc_attr( $title_id ); ?>"><?php esc_html_e( 'Team, Tasks and Delegation', 'sabri-publishing-dashboard' ); ?></h2>
	<div class="spdb-tabular-sections">
		<section class="spdb-operations-panel"><h3><?php esc_html_e( 'Tasks', 'sabri-publishing-dashboard' ); ?></h3>
			<?php if ( $can_tasks ) : ?><form class="spdb-action-form" data-spdb-operation-form data-endpoint="tasks" data-method="POST"><label><span><?php esc_html_e( 'Task title', 'sabri-publishing-dashboard' ); ?></span><input type="text" name="title" maxlength="200" required></label><label><span><?php esc_html_e( 'Description', 'sabri-publishing-dashboard' ); ?></span><textarea name="description" maxlength="2000"></textarea></label><div class="spdb-form-grid"><label><span><?php esc_html_e( 'Assignee user ID', 'sabri-publishing-dashboard' ); ?></span><input type="number" min="1" name="assignee_user_id" value="<?php echo esc_attr( (string) get_current_user_id() ); ?>" required></label><label><span><?php esc_html_e( 'Scope', 'sabri-publishing-dashboard' ); ?></span><select name="scope"><option value="own"><?php esc_html_e( 'Own', 'sabri-publishing-dashboard' ); ?></option><?php if ( ! empty( $governance_result['institutional'] ) ) : ?><option value="institution"><?php esc_html_e( 'Institution', 'sabri-publishing-dashboard' ); ?></option><?php endif; ?></select></label><label><span><?php esc_html_e( 'Priority', 'sabri-publishing-dashboard' ); ?></span><select name="priority"><option value="normal"><?php esc_html_e( 'Normal', 'sabri-publishing-dashboard' ); ?></option><option value="high"><?php esc_html_e( 'High', 'sabri-publishing-dashboard' ); ?></option><option value="urgent"><?php esc_html_e( 'Urgent', 'sabri-publishing-dashboard' ); ?></option></select></label><label><span><?php esc_html_e( 'Due at GMT', 'sabri-publishing-dashboard' ); ?></span><input type="datetime-local" name="due_at_gmt"></label></div><label><span><?php esc_html_e( 'Audit reason', 'sabri-publishing-dashboard' ); ?></span><input type="text" name="audit_reason" maxlength="500" required></label><button type="submit" class="spdb-button"><?php esc_html_e( 'Create Task', 'sabri-publishing-dashboard' ); ?></button></form><?php endif; ?>
			<?php if ( empty( $governance_result['tasks'] ) ) : ?><p class="spdb-empty-state"><?php esc_html_e( 'No eligible tasks are available.', 'sabri-publishing-dashboard' ); ?></p><?php else : ?><ul class="spdb-record-list"><?php foreach ( $governance_result['tasks'] as $task ) : ?><li><div><strong><?php echo esc_html( $task['title'] ); ?></strong><small><?php echo esc_html( $task['status'] . ' · ' . $task['priority'] ); ?></small><p><?php echo esc_html( $task['description'] ); ?></p></div></li><?php endforeach; ?></ul><?php endif; ?>
		</section>

		<?php if ( $can_delegate ) : ?><section class="spdb-operations-panel"><h3><?php esc_html_e( 'Scoped Delegations', 'sabri-publishing-dashboard' ); ?></h3><p><?php esc_html_e( 'Delegations require a current two-factor-authenticated session, expire automatically, remain revocable, and cannot grant publish-as-author, patient-data, or unrestricted export authority.', 'sabri-publishing-dashboard' ); ?></p><form class="spdb-action-form" data-spdb-operation-form data-endpoint="delegations" data-method="POST"><div class="spdb-form-grid"><label><span><?php esc_html_e( 'Delegate user ID', 'sabri-publishing-dashboard' ); ?></span><input type="number" min="1" name="delegate_user_id" required></label><label><span><?php esc_html_e( 'Start GMT', 'sabri-publishing-dashboard' ); ?></span><input type="datetime-local" name="starts_at_gmt" required></label><label><span><?php esc_html_e( 'Expiry GMT', 'sabri-publishing-dashboard' ); ?></span><input type="datetime-local" name="expires_at_gmt" required></label></div><fieldset><legend><?php esc_html_e( 'Allowed scoped actions', 'sabri-publishing-dashboard' ); ?></legend><label><input type="checkbox" name="scope[]" value="view_content"> <?php esc_html_e( 'View content projections', 'sabri-publishing-dashboard' ); ?></label><label><input type="checkbox" name="scope[]" value="manage_tasks"> <?php esc_html_e( 'Manage assigned tasks', 'sabri-publishing-dashboard' ); ?></label><label><input type="checkbox" name="scope[]" value="respond_interactions"> <?php esc_html_e( 'Respond through native interaction providers', 'sabri-publishing-dashboard' ); ?></label><label><input type="checkbox" name="scope[]" value="schedule_proposal"> <?php esc_html_e( 'Propose schedules', 'sabri-publishing-dashboard' ); ?></label></fieldset><label><span><?php esc_html_e( 'Reason', 'sabri-publishing-dashboard' ); ?></span><input type="text" name="reason" maxlength="500" required></label><button type="submit" class="spdb-button"><?php esc_html_e( 'Create Delegation', 'sabri-publishing-dashboard' ); ?></button></form><?php if ( ! empty( $governance_result['delegations'] ) ) : ?><ul class="spdb-record-list"><?php foreach ( $governance_result['delegations'] as $delegation ) : ?><li><strong><?php echo esc_html( sprintf( __( 'Delegate %d', 'sabri-publishing-dashboard' ), $delegation['delegate_user_id'] ) ); ?></strong><small><?php echo esc_html( $delegation['status'] . ' · ' . $delegation['expires_at_gmt'] ); ?></small></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>

		<?php if ( $can_rules ) : ?><section class="spdb-operations-panel"><h3><?php esc_html_e( 'Bounded Automation Rules', 'sabri-publishing-dashboard' ); ?></h3><p><?php esc_html_e( 'Automation remains human-governed, idempotent and reversible. Medical approval, patient-data publication, cure claims, impersonation, destructive deletion and unreviewed AI publication are prohibited.', 'sabri-publishing-dashboard' ); ?></p><form class="spdb-action-form" data-spdb-operation-form data-endpoint="automation-rules" data-method="POST"><div class="spdb-form-grid"><label><span><?php esc_html_e( 'Trigger', 'sabri-publishing-dashboard' ); ?></span><select name="rule_type"><option value="stale_draft_reminder"><?php esc_html_e( 'Stale draft', 'sabri-publishing-dashboard' ); ?></option><option value="failed_publication_retry"><?php esc_html_e( 'Schedule failed', 'sabri-publishing-dashboard' ); ?></option><option value="broken_source_check"><?php esc_html_e( 'Source broken', 'sabri-publishing-dashboard' ); ?></option><option value="knowledge_link_reminder"><?php esc_html_e( 'Knowledge link missing', 'sabri-publishing-dashboard' ); ?></option><option value="approved_unpublished_alert"><?php esc_html_e( 'Approved but unpublished', 'sabri-publishing-dashboard' ); ?></option></select></label><input type="hidden" name="event_key" value="publishing_state_changed"><label><span><?php esc_html_e( 'Action', 'sabri-publishing-dashboard' ); ?></span><select name="action_key"><option value="send_reminder"><?php esc_html_e( 'Send reminder through File 19', 'sabri-publishing-dashboard' ); ?></option><option value="enqueue_native_retry"><?php esc_html_e( 'Queue bounded native retry', 'sabri-publishing-dashboard' ); ?></option><option value="create_task"><?php esc_html_e( 'Create task', 'sabri-publishing-dashboard' ); ?></option></select></label></div><label><span><?php esc_html_e( 'Audit reason', 'sabri-publishing-dashboard' ); ?></span><input type="text" name="audit_reason" maxlength="500" required></label><button type="submit" class="spdb-button"><?php esc_html_e( 'Create Disabled Rule', 'sabri-publishing-dashboard' ); ?></button></form><?php if ( ! empty( $governance_result['automation_rules'] ) ) : ?><ul class="spdb-record-list"><?php foreach ( $governance_result['automation_rules'] as $rule ) : ?><li><div><strong><?php echo esc_html( $rule['rule_type'] ); ?></strong><small><?php echo esc_html( $rule['status'] . ' · ' . $rule['event_key'] . ' → ' . (string) ( $rule['action']['action_key'] ?? '' ) ); ?></small></div><?php if ( in_array( $rule['status'], array( 'enabled', 'disabled' ), true ) ) : ?><form class="spdb-action-form" data-spdb-operation-form data-endpoint="automation-rules/<?php echo esc_attr( $rule['rule_id'] ); ?>/status" data-method="POST" data-confirm="true"><input type="hidden" name="version" value="<?php echo esc_attr( (string) $rule['version'] ); ?>"><input type="hidden" name="status" value="<?php echo esc_attr( 'enabled' === $rule['status'] ? 'disabled' : 'enabled' ); ?>"><button class="spdb-button spdb-button--secondary" type="submit"><?php echo 'enabled' === $rule['status'] ? esc_html__( 'Disable', 'sabri-publishing-dashboard' ) : esc_html__( 'Enable', 'sabri-publishing-dashboard' ); ?></button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>
	</div>
	<div class="spdb-live-region" role="status" aria-live="polite" data-spdb-operation-status></div>
</section>
